<template><aside class="editor-panel properties-panel" aria-label="Widget settings"><template v-if="widget&&definition"><header><p class="overlay-kicker">Selected widget</p><input :value="widget.name" aria-label="Widget name" @change="changeName"></header><fieldset><legend>Frame</legend><div class="property-grid"><label v-for="key in ['x','y','width','height']" :key="key"><span>{{ key.toUpperCase() }}</span><input type="number" :value="widget.frame[key]" min="0" @change="frameChange(key,$event)"></label></div></fieldset><fieldset><legend>{{ definition.displayName }} settings</legend><label v-for="field in definition.settings" :key="field.key" class="property-field"><span>{{ field.label }}</span><input v-if="field.type==='checkbox'" type="checkbox" :checked="widget.settings[field.key]" @change="settingChange(field,$event.target.checked)"><textarea v-else-if="field.type==='textarea'" :value="widget.settings[field.key]" @change="settingChange(field,$event.target.value)"></textarea><select v-else-if="field.type==='select'" :value="widget.settings[field.key]" @change="settingChange(field,$event.target.value)"><option v-for="option in field.options" :key="option" :value="option">{{ option }}</option></select><input v-else :type="field.type" :value="widget.settings[field.key]" :min="field.min" :max="field.max" :step="field.step" @input="settingChange(field,$event.target.value)"></label></fieldset></template><div v-else class="empty-panel"><b>No widget selected</b><p>Select a widget on the canvas or in Layers.</p></div></aside></template>
<script setup>import { computed } from 'vue'; import { widgetRegistry } from '../../overlays/widgetRegistry.js'; const props=defineProps({widget:Object}); const emit=defineEmits(['change']); const definition=computed(()=>props.widget?widgetRegistry[props.widget.type]:null); function patch(next){emit('change',{...props.widget,...next,updatedAt:new Date().toISOString()})} function changeName(e){patch({name:e.target.value})} function frameChange(key,e){patch({frame:{...props.widget.frame,[key]:Math.max(0,Number(e.target.value))}})} function settingChange(field,value){const numeric=['number','range'].includes(field.type);patch({settings:{...props.widget.settings,[field.key]:numeric?Number(value):value}})}</script>
